------------ lifeCycle ------------


function UIBattlingMultiStagePanel:CleanProperties()
    self.RT_NodeParent = nil
    self.RT_Node = nil
    self.nodeList = nil
end

function UIBattlingMultiStagePanel:InitNodes(stageNum)
    local goList = {}
    table.insert(goList, self.RT_Node)
    for i = 2, stageNum, 1 do
        local go = KTool.Instantiate(self.RT_NodeParent.gameObject, self.RT_Node.gameObject)
        table.insert(goList, go)
    end

    self.nodeList = {}
    for i, go in ipairs(goList) do
        KTool.SetActive(go, true)
        local item = {}
        item.anim = go:GetComponent(typeof(Animation))
        item.simg = go.transform:Find("ImgIcon"):GetComponent(typeof(UISwitchImage))
        table.insert(self.nodeList, item)
    end
end

function UIBattlingMultiStagePanel:SetStage(index)
    for i, node in ipairs(self.nodeList) do
        local node = self.nodeList[i]
        if i < index then
            node.anim:Play(EndAnim)
            node.simg.Status = 2
        elseif i == index then
            node.anim:Play(LoopAnim)
        end
    end
end

return UIBattlingMultiStagePanel